const marked = {
  parse: function(text, theme = 'yellow') {
    if (!text) return '';

    text = text.replace(/&/g, '&amp;')
               .replace(/</g, '&lt;')
               .replace(/>/g, '&gt;');

    const themes = {
      yellow: {
        p: 'margin:1.2em 0;line-height:1.8;color:#1a1a1a;font-size:16px;',
        h1: 'margin:1.8em 0 0.8em;font-weight:700;color:#1a1a1a;font-size:1.8em;border-bottom:2px solid #d97706;padding-bottom:8px;',
        h2: 'margin:1.6em 0 0.6em;font-weight:600;color:#1a1a1a;font-size:1.4em;text-align:center;padding-bottom:8px;border-bottom:2px solid #d97706;width:60%;margin-left:20%;',
        h3: 'margin:1.4em 0 0.5em;font-weight:600;color:#1a1a1a;font-size:1.2em;',
        h4: 'margin:1.2em 0 0.4em;font-weight:600;color:#1a1a1a;font-size:1.1em;',
        h5: 'margin:1em 0 0.3em;font-weight:600;color:#1a1a1a;font-size:1em;',
        h6: 'margin:0.8em 0 0.3em;font-weight:600;color:#1a1a1a;font-size:0.95em;',
        blockquote: 'border-radius:8px;border:2px solid #f59e0b;padding:16px 20px;margin:1.5em 0;color:#78350f;background:#fef3c7;font-style:normal;',
        code: 'background:#fef3c7;padding:3px 8px;border-radius:4px;font-family:Consolas,Monaco,monospace;font-size:14px;color:#d97706;',
        pre: 'background:#fef3c7;padding:16px;border-radius:8px;overflow-x:auto;margin:1.5em 0;font-family:Consolas,Monaco,monospace;font-size:14px;color:#92400e;border:1px solid #fbbf24;',
        strong: 'font-weight:700;color:#d97706;',
        a: 'color:#d97706;text-decoration:none;border-bottom:1px solid #fcd34d;',
        ul: 'margin:1.2em 0;padding-left:1.8em;',
        ol: 'margin:1.2em 0;padding-left:1.8em;',
        li: 'margin:0.5em 0;line-height:1.7;color:#1a1a1a;',
        hr: 'border:none;border-top:2px dashed #fbbf24;margin:2em 0;',
        table: 'border-collapse:collapse;width:100%;margin:1.5em 0;',
        th: 'border:1px solid #fbbf24;padding:10px 14px;text-align:left;background:#fef3c7;color:#92400e;font-weight:600;',
        td: 'border:1px solid #fbbf24;padding:10px 14px;text-align:left;color:#1a1a1a;'
      },
      purple: {
        p: 'margin:1.2em 0;line-height:1.8;color:#374151;font-size:16px;text-indent:2em;',
        h1: 'margin:1.8em 0 1em;font-weight:700;color:#374151;font-size:1.8em;',
        h2: 'margin:1.6em 0 0.8em;font-weight:600;color:#6b21a8;font-size:1.4em;padding-left:12px;border-left:4px solid #a855f7;',
        h3: 'margin:1.4em 0 0.6em;font-weight:600;color:#4c1d95;font-size:1.2em;border-bottom:1px solid #e9d5ff;padding-bottom:5px;',
        h4: 'margin:1.2em 0 0.5em;font-weight:600;color:#4c1d95;font-size:1.1em;',
        h5: 'margin:1em 0 0.4em;font-weight:600;color:#4c1d95;font-size:1em;',
        h6: 'margin:0.8em 0 0.3em;font-weight:600;color:#4c1d95;font-size:0.95em;',
        blockquote: 'border-radius:6px;padding:16px 20px;margin:1.5em 0;color:#6b21a8;background:#f3e8ff;border-left:4px solid #a855f7;font-style:normal;',
        code: 'background:#f3e8ff;padding:3px 8px;border-radius:4px;font-family:Consolas,Monaco,monospace;font-size:14px;color:#7c3aed;',
        pre: 'background:#1e1b4b;padding:16px;border-radius:8px;overflow-x:auto;margin:1.5em 0;font-family:Consolas,Monaco,monospace;font-size:14px;color:#c4b5fd;',
        strong: 'font-weight:700;color:#6b21a8;',
        a: 'color:#8b5cf6;text-decoration:none;border-bottom:1px solid #ddd6fe;',
        ul: 'margin:1.2em 0;padding-left:1.8em;',
        ol: 'margin:1.2em 0;padding-left:1.8em;',
        li: 'margin:0.5em 0;line-height:1.7;color:#374151;',
        hr: 'border:none;border-top:1px dashed #ddd6fe;margin:2em 0;',
        table: 'border-collapse:collapse;width:100%;margin:1.5em 0;',
        th: 'border:1px solid #ddd6fe;padding:10px 14px;text-align:left;background:#faf5ff;color:#4c1d95;font-weight:600;',
        td: 'border:1px solid #ddd6fe;padding:10px 14px;text-align:left;color:#374151;'
      },
      blue: {
        p: 'margin:1.2em 0;line-height:1.8;color:#1e293b;font-size:16px;',
        h1: 'margin:1.8em 0 1em;font-weight:700;color:#1e293b;font-size:1.8em;',
        h2: 'margin:1.6em 0 0.8em;font-weight:600;color:#4f46e5;font-size:1.4em;padding-left:12px;border-left:4px solid #8b5cf6;',
        h3: 'margin:1.4em 0 0.6em;font-weight:600;color:#4338ca;font-size:1.2em;',
        h4: 'margin:1.2em 0 0.5em;font-weight:600;color:#4338ca;font-size:1.1em;',
        h5: 'margin:1em 0 0.4em;font-weight:600;color:#4338ca;font-size:1em;',
        h6: 'margin:0.8em 0 0.3em;font-weight:600;color:#4338ca;font-size:0.95em;',
        blockquote: 'border-radius:8px;padding:18px 24px;margin:1.5em 0;color:#4338ca;background:#e0e7ff;border-left:4px solid #6366f1;font-style:normal;',
        code: 'background:#e0e7ff;padding:3px 8px;border-radius:4px;font-family:Consolas,Monaco,monospace;font-size:14px;color:#4f46e5;',
        pre: 'background:#1e1b4b;padding:16px;border-radius:8px;overflow-x:auto;margin:1.5em 0;font-family:Consolas,Monaco,monospace;font-size:14px;color:#a5b4fc;',
        strong: 'font-weight:700;color:#4f46e5;',
        a: 'color:#6366f1;text-decoration:none;border-bottom:1px solid #c7d2fe;',
        ul: 'margin:1.2em 0;padding-left:1.8em;',
        ol: 'margin:1.2em 0;padding-left:1.8em;',
        li: 'margin:0.5em 0;line-height:1.7;color:#1e293b;',
        hr: 'border:none;border-top:2px solid #c7d2fe;margin:2em 0;',
        table: 'border-collapse:collapse;width:100%;margin:1.5em 0;',
        th: 'border:1px solid #c7d2fe;padding:10px 14px;text-align:left;background:#f0f4ff;color:#4338ca;font-weight:600;',
        td: 'border:1px solid #c7d2fe;padding:10px 14px;text-align:left;color:#1e293b;'
      },
      orange: {
        p: 'margin:1.2em 0;line-height:1.8;color:#451a03;font-size:16px;',
        h1: 'margin:1.8em 0 1em;font-weight:700;color:#451a03;font-size:1.8em;',
        h2: 'margin:1.6em 0 0.8em;font-weight:600;color:#ea580c;font-size:1.4em;padding-left:12px;border-left:4px solid #fb923c;',
        h3: 'margin:1.4em 0 0.6em;font-weight:600;color:#c2410c;font-size:1.2em;',
        h4: 'margin:1.2em 0 0.5em;font-weight:600;color:#c2410c;font-size:1.1em;',
        h5: 'margin:1em 0 0.4em;font-weight:600;color:#c2410c;font-size:1em;',
        h6: 'margin:0.8em 0 0.3em;font-weight:600;color:#c2410c;font-size:0.95em;',
        blockquote: 'border-radius:8px;padding:18px 24px;margin:1.5em 0;color:#9a3412;background:#ffedd5;border-left:4px solid #fb923c;font-style:normal;',
        code: 'background:#ffedd5;padding:3px 8px;border-radius:4px;font-family:Consolas,Monaco,monospace;font-size:14px;color:#ea580c;',
        pre: 'background:#431407;padding:16px;border-radius:8px;overflow-x:auto;margin:1.5em 0;font-family:Consolas,Monaco,monospace;font-size:14px;color:#fed7aa;',
        strong: 'font-weight:700;color:#ea580c;',
        a: 'color:#fb923c;text-decoration:none;border-bottom:1px solid #fdba74;',
        ul: 'margin:1.2em 0;padding-left:1.8em;',
        ol: 'margin:1.2em 0;padding-left:1.8em;',
        li: 'margin:0.5em 0;line-height:1.7;color:#451a03;',
        hr: 'border:none;border-top:2px solid #fdba74;margin:2em 0;',
        table: 'border-collapse:collapse;width:100%;margin:1.5em 0;',
        th: 'border:1px solid #fdba74;padding:10px 14px;text-align:left;background:#fff7ed;color:#c2410c;font-weight:600;',
        td: 'border:1px solid #fdba74;padding:10px 14px;text-align:left;color:#451a03;'
      },
      green: {
        p: 'margin:1.2em 0;line-height:1.8;color:#14532d;font-size:16px;',
        h1: 'margin:1.8em 0 1em;font-weight:700;color:#14532d;font-size:1.8em;',
        h2: 'margin:1.6em 0 0.8em;font-weight:600;color:#166534;font-size:1.4em;background:#22c55e;color:#ffffff;padding:10px 16px;border-radius:4px;text-align:center;',
        h3: 'margin:1.4em 0 0.6em;font-weight:600;color:#15803d;font-size:1.2em;border-bottom:2px solid #86efac;padding-bottom:5px;',
        h4: 'margin:1.2em 0 0.5em;font-weight:600;color:#15803d;font-size:1.1em;',
        h5: 'margin:1em 0 0.4em;font-weight:600;color:#15803d;font-size:1em;',
        h6: 'margin:0.8em 0 0.3em;font-weight:600;color:#15803d;font-size:0.95em;',
        blockquote: 'border-radius:6px;padding:16px 20px;margin:1.5em 0;color:#166534;background:#dcfce7;font-style:normal;border-left:4px solid #22c55e;',
        code: 'background:#dcfce7;padding:3px 8px;border-radius:4px;font-family:Consolas,Monaco,monospace;font-size:14px;color:#15803d;',
        pre: 'background:#14532d;padding:16px;border-radius:8px;overflow-x:auto;margin:1.5em 0;font-family:Consolas,Monaco,monospace;font-size:14px;color:#86efac;',
        strong: 'font-weight:700;color:#166534;',
        a: 'color:#22c55e;text-decoration:none;border-bottom:1px solid #86efac;',
        ul: 'margin:1.2em 0;padding-left:1.8em;',
        ol: 'margin:1.2em 0;padding-left:1.8em;',
        li: 'margin:0.5em 0;line-height:1.7;color:#14532d;',
        hr: 'border:none;border-top:2px solid #86efac;margin:2em 0;',
        table: 'border-collapse:collapse;width:100%;margin:1.5em 0;',
        th: 'border:1px solid #86efac;padding:10px 14px;text-align:left;background:#f0fdf4;color:#15803d;font-weight:600;',
        td: 'border:1px solid #86efac;padding:10px 14px;text-align:left;color:#14532d;'
      }
    };

    const t = themes[theme] || themes.yellow;
    const lines = text.split('\n');
    const result = [];
    let i = 0;
    let inCodeBlock = false;
    let codeContent = [];

    while (i < lines.length) {
      const line = lines[i];

      if (line.startsWith('```')) {
        if (!inCodeBlock) {
          inCodeBlock = true;
          codeContent = [];
        } else {
          inCodeBlock = false;
          result.push('<pre style="' + t.pre + '"><code>' + codeContent.join('\n') + '</code></pre>');
        }
        i++;
        continue;
      }

      if (inCodeBlock) {
        codeContent.push(line);
        i++;
        continue;
      }

      if (line.match(/^#{1,6}\s/)) {
        const match = line.match(/^(#{1,6})\s(.+)$/);
        const level = match[1].length;
        result.push('<h' + level + ' style="' + t['h' + level] + '">' + this.parseInline(match[2], t) + '</h' + level + '>');
        i++;
        continue;
      }

      if (line.match(/^[-*+]\s/)) {
        result.push('<ul style="' + t.ul + '">');
        while (i < lines.length && lines[i].match(/^[-*+]\s/)) {
          const item = lines[i].replace(/^[-*+]\s/, '');
          result.push('<li style="' + t.li + '">' + this.parseInline(item, t) + '</li>');
          i++;
        }
        result.push('</ul>');
        continue;
      }

      if (line.match(/^\d+\.\s/)) {
        result.push('<ol style="' + t.ol + '">');
        while (i < lines.length && lines[i].match(/^\d+\.\s/)) {
          const item = lines[i].replace(/^\d+\.\s/, '');
          result.push('<li style="' + t.li + '">' + this.parseInline(item, t) + '</li>');
          i++;
        }
        result.push('</ol>');
        continue;
      }

      if (line.match(/^\|.+\|/)) {
        const tableLines = [];
        while (i < lines.length && lines[i].match(/^\|.+\|/)) {
          tableLines.push(lines[i]);
          i++;
        }
        result.push(this.parseTable(tableLines, t));
        continue;
      }

      if (line.match(/^>/)) {
        const quotes = [];
        while (i < lines.length && lines[i].match(/^>/)) {
          quotes.push(lines[i].replace(/^>\s*/, ''));
          i++;
        }
        result.push('<blockquote style="' + t.blockquote + '">' + this.parseInline(quotes.join(' '), t) + '</blockquote>');
        continue;
      }

      if (line.match(/^---$/)) {
        result.push('<hr style="' + t.hr + '">');
        i++;
        continue;
      }

      if (line.trim() === '') {
        i++;
        continue;
      }

      result.push('<p style="' + t.p + '">' + this.parseInline(line, t) + '</p>');
      i++;
    }

    return result.join('\n');
  },

  parseInline: function(text, theme) {
    if (!text) return '';

    text = text.replace(/&amp;/g, '&')
               .replace(/&lt;/g, '<')
               .replace(/&gt;/g, '>');

    text = text.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1" style="max-width:100%;height:auto;border-radius:4px;margin:1em 0;">');

    text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" style="' + theme.a + '">$1</a>');

    text = text.replace(/\*\*([\s\S]+?)\*\*/g, '<strong style="' + theme.strong + '">$1</strong>');

    text = text.replace(/\*([\s\S]+?)\*/g, '<em style="font-style:italic;">$1</em>');

    text = text.replace(/~~([\s\S]+?)~~/g, '<del style="text-decoration:line-through;">$1</del>');

    text = text.replace(/`([^`]+)`/g, '<code style="' + theme.code + '">$1</code>');

    return text;
  },

  parseTable: function(lines, theme) {
    if (lines.length < 2) return '';

    const headers = lines[0].split('|').slice(1, -1).map(h => h.trim());
    const alignRow = lines[1];
    const alignments = alignRow.split('|').slice(1, -1).map(a => {
      if (a.includes(':') && a.includes('-')) return 'center';
      if (a.includes(':')) return 'left';
      return 'left';
    });

    let html = '<table style="' + theme.table + '">';
    html += '<thead><tr>';
    headers.forEach((h, i) => {
      html += '<th style="' + theme.th.replace('text-align:left', 'text-align:' + alignments[i]) + '">' + h + '</th>';
    });
    html += '</tr></thead><tbody>';

    for (let i = 2; i < lines.length; i++) {
      const cells = lines[i].split('|').slice(1, -1).map(c => c.trim());
      html += '<tr>';
      cells.forEach((c, j) => {
        html += '<td style="' + theme.td.replace('text-align:left', 'text-align:' + alignments[j]) + '">' + this.parseInline(c, theme) + '</td>';
      });
      html += '</tr>';
    }

    html += '</tbody></table>';
    return html;
  }
};